import{z as i,x as s,o as e,c as p,q as t,j as B,D as l,d as A,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"失败模式清单","description":"","frontmatter":{"title":"失败模式清单","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-failure-catalog.md","filePath":"llm/lc-failure-catalog.md","lastUpdated":1791413859000}'),d={name:"llm/lc-failure-catalog.md"};function m(C,E,f,D,h,c){const r=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=t('<h1 id="失败模式清单" tabindex="-1">失败模式清单 <a class="header-anchor" href="#失败模式清单" aria-label="Permalink to &quot;失败模式清单&quot;">​</a></h1><div class="epigraph"><p>长上下文服务的故障是跨层的复合故障；监控每一格都绿、用户侧是错的，是它的标准长相。</p><footer>—— 据本课程各课的失败条目整理</footer></div><p><a href="/llm/lc-cost-case">上一课</a>把优化杠杆走成链条。本课是第二门综合课，不立新机制，把前面各课散落的失败编成一张清单，按层排列：容量、调度、正确性、质量、语义。清单的用法不是背诵，是值班时的排查顺序——先查哪层，取决于哪层最便宜、最能证伪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单看任何一门课，失败都是「已知机制」；合到一起跑，长上下文服务的标准故障却是复合的：碎片引发抢占，抢占触发降级，降级没有标注，用户看到的是「模型变笨了」——四层各绿一格，体验全错。逐课回翻效率太低，值班需要一张按层索引、条目化、可勾选的清单。缺的还有排查顺序：从哪层查起，决定了一次故障是十五分钟的 grep 还是一次通宵的压测。</p><p><span class="marginnote">常见误区：初学者容易从最底层（显存、驱动）查起，觉得「越底层越根本」。实际上长上下文服务的大多数报障是语义与正确性层的配置问题，一条 grep 就能证伪；而要稳定复现调度与容量层故障，往往得压测一整晚。先查便宜的层，不是因为它们更常见，而是因为证伪成本最低。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条按「症状—根因—指针」编目。容量层：满池 OOM 与抢占风暴，根因是准入按条数不按页数（<a href="/llm/lc-memory-account">显存账课</a>）；池子没满却接不进长请求，根因是慢性碎片（<a href="/llm/kv-paging-fragmentation">分页课</a>）；把「支持 128K」当常驻预留，是<a href="/llm/kv-longcontext-budget">预算课</a>警告过的老错复发。调度层：ITL 出现秒级凹口，根因是队头长前填 stall（<a href="/llm/chunked-prefill">切块基础课</a>）；TTFT 反而劣化，根因是切块过碎的带宽税（<a href="/llm/lc-chunked-prefill">深入课</a>）；命中率全绿而单副本过载，根因是缓存羊群、路由失亲和（<a href="/llm/sglang-router">router 课</a>）。正确性层：长文档答案质量随机波动，根因是缓存键漏位置配置版本（<a href="/llm/lc-extrapolation-serving">外推课</a>）；滑窗模型窗口内崩，根因是汇点页被滚动驱逐（<a href="/llm/attention-sink">汇点课</a>）；跨租户看见彼此的内容，根因是命中键漏权限（<a href="/llm/lc-multidoc-workload">多文档课</a>）。质量层：把中间丢失当「模型不行」去换模型，先测排列（<a href="/llm/niah">针测课</a>）；把 context rot 当检索召回问题去调 \\(k\\)（<a href="/llm/context-rot">context rot 课</a>）；超有效窗口静默降质，是外推课三分支没落地。语义层：截断被当成完整回答进多轮历史，finish_reason 没分账（<a href="/llm/stop-sequences">停止语义课</a>）；长输出中段降级无标注（<a href="/llm/lc-longoutput-streaming">流式课</a>）；答案对、引用错，是位置元数据没传（<a href="/llm/lc-retrieval-hybrid-serving">混合课</a>）。</p>',8)),(e(),B(n,null,{default:l(()=>[o(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALARM%5B%22%E7%94%A8%E6%88%B7%E6%8A%A5%E9%9A%9C%E6%88%96%E6%8A%95%E8%AF%89%22%5D%20--%3E%20SEM%5B%22%E8%AF%AD%E4%B9%89%E5%B1%82%EF%BC%9Afinish_reason%E3%80%81%E6%88%AA%E6%96%AD%E7%8E%87%E3%80%81%E8%AD%A6%E5%91%8A%E5%A4%B4%22%5D%0A%20%20SEM%20--%3E%20CORR%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E5%B1%82%EF%BC%9A%E9%85%8D%E7%BD%AE%E5%AE%A1%E8%AE%A1%E3%80%81%E9%92%88%E6%B5%8B%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20CORR%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%B1%82%EF%BC%9Astall%E3%80%81%E5%91%BD%E4%B8%AD%E7%8E%87%E3%80%81%E4%BA%B2%E5%92%8C%22%5D%0A%20%20SCHED%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E5%B1%82%EF%BC%9A%E6%B0%B4%E4%BD%8D%E3%80%81%E7%A2%8E%E7%89%87%E3%80%81%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20SEM%20--%3E%7C%22%E6%9C%89%E5%BC%82%E5%B8%B8%22%7C%20FIX%5B%22%E6%8C%89%E6%9D%A1%E7%9B%AE%E6%8C%87%E9%92%88%E5%9B%9E%E6%9C%BA%E5%88%B6%E8%AF%BE%E4%BF%AE%E5%A4%8D%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"排查顺序按「便宜且可证伪」排，机制在成本：语义层查一次是 grep 日志，正确性层次之——离线针测与配置审计即可复现；调度与容量层最后——要压测才稳定复现。所以顺序是语义、正确性、调度、容量，图里从上往下。清单的第二个用途是把修法锚回机制：每条失败对应一门课的一笔账或一条契约，修复动作不是「加监控」，是回到那门课把账补全、把契约落地——监控只负责发现，清单负责把发现接回机制。复合故障按「最先可观测的那层」立案，但归因要跨层写完整，否则下次还在同一处断裂。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"一条排查经验：先看 finish_reason 与截断率的分布，再看任何性能曲线——停止协议与降级语义的回归，往往比 TPOT 曲线早几天发出信号；等曲线动了，故障已经过了潜伏期。")],-1)),E[6]||(E[6]=a("p",null,"复合故障最典型的传导链值得单独画出：碎片引发抢占，抢占触发降级，降级没有标注，最终用户看到的只是「模型变笨了」——而每一层自己的监控灯始终是绿的。",-1)),(e(),B(n,null,{default:l(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20FRAG%5B%22KV%20%E7%BC%93%E5%AD%98%E6%85%A2%E6%80%A7%E7%A2%8E%E7%89%87%22%5D%20--%3E%7C%22%E9%95%BF%E8%AF%B7%E6%B1%82%E6%8E%A5%E4%B8%8D%E8%BF%9B%E5%86%85%E5%AD%98%22%7C%20PRE%5B%22%E8%AF%B7%E6%B1%82%E8%A2%AB%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20PRE%20--%3E%7C%22%E7%B3%BB%E7%BB%9F%E8%B5%B0%E9%99%8D%E7%BA%A7%E8%B7%AF%E5%BE%84%22%7C%20DEG%5B%22%E7%AD%94%E6%A1%88%E8%B4%A8%E9%87%8F%E9%9D%99%E9%BB%98%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DEG%20--%3E%7C%22%E9%99%8D%E7%BA%A7%E6%9C%AA%E6%A0%87%E6%B3%A8%E3%80%81%E6%9C%AA%E8%AE%A1%E6%95%B0%22%7C%20USER%5B%22%E7%94%A8%E6%88%B7%E6%84%9F%E7%9F%A5%EF%BC%9A%E6%A8%A1%E5%9E%8B%E5%8F%98%E7%AC%A8%E4%BA%86%22%5D%0A%20%20CAP%5B%22%E5%AE%B9%E9%87%8F%E5%B1%82%E7%9B%91%E6%8E%A7%E7%81%AF%EF%BC%9A%E7%BB%BF%22%5D%20-.-%3E%7C%22%E7%A2%8E%E7%89%87%E6%9C%AA%E8%BE%BE%E5%91%8A%E8%AD%A6%E9%98%88%E5%80%BC%22%7C%20FRAG%0A%20%20SEM%5B%22%E8%AF%AD%E4%B9%89%E5%B1%82%E7%9B%91%E6%8E%A7%E7%81%AF%EF%BC%9A%E7%BB%BF%22%5D%20-.-%3E%7C%22%E6%B2%A1%E6%9C%89%E9%99%8D%E7%BA%A7%E6%8C%87%E6%A0%87%E5%8F%AF%E7%9C%8B%22%7C%20USER%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p>这张图回答的问题是：为什么各层监控全绿、用户侧却是错的。故障的每一跳都发生在「两层之间的缝隙」里——碎片与抢占是容量与调度的交界，降级与标注是质量与语义的交界；单层监控只看自己格内的指标，跨层传导的因果链上没有任何一盏灯会变红。</p><p><span class="marginnote">术语翻译：「复合故障」不是一个组件坏了，而是多个各自「正常」的组件叠加出的错——每一层看自己的指标都合格，合起来却是用户可见的故障。它难排查，恰恰因为没有任何单一指标变红，只能靠跨层清单把因果链接起来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">直觉类比：「症状—根因—指针」的编目法可以想象成医院的分诊手册：症状是病人主诉，根因是病灶，指针是转诊单。值班人员不需要背下每种病，只需要按手册把当前症状匹配到条目，再顺着指针「转诊」到对应的机制课——手册的价值在格式统一，不在条目数量。</span></p><p>清单不是分类学：同一事故常跨两层，条目间没有互斥边界。清单也不完备：新配置——新的外推表、新的压缩刀、新的混合部署——会带来新条目；本课的编目法（症状、根因、指针、排查层）比条目本身耐用，新增失败按同一格式续写。最后，清单覆盖服务侧；模型侧的长文本能力缺陷（真实的推理失败，而非服务错误）不在本清单，先过<a href="/llm/lc-eval-serving">评测服务化</a>的门禁再定性，是两类问题的分界线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长上下文故障是跨层复合故障：按容量、调度、正确性、质量、语义五层编目。</li><li>排查按「便宜且可证伪」：语义层先行（grep 可查），容量层殿后（压测可复现）。</li><li>每条失败锚回一门课的账或契约；修复是补账落地契约，不是加监控。</li><li>复合故障按最先可观测层立案，归因跨层写完整。</li><li>出处：据本课程各课条目整理；停止语义与降级标注口径同本仓库 stop sequences 课。</li></ul>',7))])}const g=i(d,[["render",m]]);export{F as __pageData,g as default};
